cpp.setup:
auto* anchor = new fluent::basicinput::Button(QStringLiteral("Workspace"), %PARENT%);
anchor->setFixedSize(112, 32);
anchor->move(234, 129);
anchor->show();
auto* control = new fluent::dialogs_flyouts::CoachMark(%PARENT%);
control->setCardSize(QSize(210, 102));
control->setTarget(anchor);
auto* layout = new QVBoxLayout(control->contentHost());
layout->setContentsMargins(14, 10, 14, 10);
layout->setSpacing(4);
auto* heading = new fluent::textfields::Label(QStringLiteral("New workspace"), control->contentHost());
heading->setFluentTypography(Typography::FontRole::BodyStrong);
layout->addWidget(heading);
auto* body = new fluent::textfields::Label(QStringLiteral("Switch views or pin folders here."), control->contentHost());
body->setWordWrap(true);
body->setTextColorRole(fluent::textfields::Label::TextColorRole::Secondary);
layout->addWidget(body);
layout->addStretch(1);
auto* acknowledge = new fluent::basicinput::Button(QStringLiteral("Got it"), control->contentHost());
acknowledge->setFluentStyle(fluent::basicinput::Button::Accent);
acknowledge->setFixedHeight(26);
layout->addWidget(acknowledge, 0, Qt::AlignRight);
QObject::connect(acknowledge, &fluent::basicinput::Button::clicked, control, &fluent::dialogs_flyouts::CoachMark::close);
QObject::connect(anchor, &fluent::basicinput::Button::clicked, control, &fluent::dialogs_flyouts::CoachMark::open);
control->open();
